def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_sequence():
    # a_1 = 10
    a = {1: 10}

    # Calculate a_2 through a_6
    for n in range(1, 6):
        # a_{n+1} = 6a_n - 2^{n+2} - 3^{n+1} + 5
        a_n = a[n]
        n_plus_1 = n + 1

        a_n_plus_1 = 6 * a_n - (2**(n_plus_1 + 1)) - (3**(n_plus_1)) + 5
        a[n_plus_1] = a_n_plus_1

    # Calculate prime factorizations and format output
    results = {}
    for n, an in a.items():
        factors = prime_factorization(an)

        # Format the factorization string
        factor_str = " * ".join([f"{p}^{e}" for p, e in factors.items()])

        results[n] = {
            "value": an,
            "factors": factors,
            "factorization_str": factor_str
        }

    return results

results = calculate_sequence()

# Print results in a format suitable for note taking
