    else:
        print(f"a_{n} not calculated (should not happen)")

def calculate_a(n):
    a = {}
    a[1] = 10
    for i in range(1, n):
        # a_{i+1} = 6a_i - 2^{i+2} - 3^{i+1} + 5
        a[i+1] = 6 * a[i] - (2**(i+2)) - (3**(i+1)) + 5
    return a

results = calculate_a(5)
for n, val in results.items():
    print(f"a_{n} = {val}")

from sympy import factorint

def calculate_a_n(n):
    """Calculates a_n using the closed form a_n = 6^n + 2^n + 3^n - 1."""
    return 6**n + 2**n + 3**n - 1

n_values = [7, 8, 9, 10]
results = {}
print("Calculating a_n and finding prime factorizations:")

for n in n_values:
    a_n = calculate_a_n(n)
    factorization = factorint(a_n)
    results[n] = {
        "value": a_n,
        "factorization": factorization
    }
    print(f"a_{n} = {a_n}. Prime Factorization: {factorization}")

print("\nSummary of results:")
for n, data in results.items():
    print(f"n={n}: Value={data['value']}, Factors={data['factorization']}")

